contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address addr) public payable {
        require(true);
        bool approved = c.approvedToLog(addr);
        assert(approved == (addr == address(this)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address logger, bool status) public payable {
        require(true);
        c.setApprovedLogger(logger, status);
        bool approved = c.approvedToLog(logger);
        assert(approved == status);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address logger) public payable {
        require(logger != address(this));
        bool approved = c.approvedToLog(logger);
        assert(!approved);
    }

    receive() external payable {}
}
